&#x27;) {           if (skipping) {             count = skip_post + skip_pre;             skipping = count == 0;             ob-&gt;sputn(&amp;sub[0], sub.size());           } else if (--count == 0) {             skipping = true;           }           ob-&gt;sputc(c);         } else if (!skipping)           ob-&gt;sputc(c);       }     }</code></pre>
